                    _ = try shell.create(result.parent.?, result.name, .{ .file = .empty });
                } else if (result.node) |node| {
                    node.modified = shell.clock;
                } else try shell.say("touch: cannot touch '{s}': {s}", .{ path, result.failure.reason() });
